@RunWith(MockitoJUnitRunner.class)
public class UntypedObjectDeserializer_createContextual_TriageGen1Test {

    @Mock
    private DeserializationContext ctxt;

    @Mock
    private BeanProperty property;





    /**
     * Tests the branch where _numberDeserializer is NOT null.
     * Expected: returns 'this'
     */
    @Test
    public void testCreateContextual_ReturnsThis_WhenNumberDeserializerNotNull() throws Exception {
        // Since we cannot inject _numberDeserializer directly via constructor easily without 
        // more types, we rely on the fact that if any field is set, it returns 'this'.
        // We can use a subclass to bypass the protected/private limitations if needed, 
        // but here we test the logic: if the condition (null && null && null && null) fails.

        // We'll use a subclass to simulate a non-null state if the constructor doesn't cover it.
        class TestUntypedObjectDeserializer extends UntypedObjectDeserializer {
            private final boolean simulateNonNull;
            public TestUntypedObjectDeserializer(boolean simulateNonNull) {
                super();
                this.simulateNonNull = simulateNonNull;
            }

            @Override
            public JsonDeserializer<?> createContextual(DeserializationContext ctxt, BeanProperty property) throws com.fasterxml.jackson.databind.JsonMappingException {
                // This is a trick to test the logic of the parent method by forcing the if condition to fail
                // However, the requirement is to test the method as written.
                // Since we cannot set private fields, we use the provided constructor.
                return super.createContextual(ctxt, property);
            }
        }

        // Using the constructor with types to ensure _mapDeserializer or _listDeserializer is not null
        com.fasterxml.jackson.databind.JavaType mockListType = mock(com.fasterxml.jackson.databind.JavaType.class);
        com.fasterxml.jackson.databind.JavaType mockMapType = mock(com.fasterxml.jackson.databind.JavaType.class);
        UntypedObjectDeserializer deserializer = new UntypedObjectDeserializer(mockListType, mockMapType);

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);
        assertEquals(deserializer, result);
    }


}

